    /** Registry lookup every iconGlyph surface composes: the nearest
     *  authored grid ≤ the requested size renders and scales to frame. */
    fun variant(named: String, size: Dp): FsdsGlyphVariant? {
        val byGrid = variants[named] ?: return null
        if (byGrid.isEmpty()) return null
        val grids = byGrid.keys.sorted()
        val grid = grids.lastOrNull { it <= size.value } ?: grids.first()
        return byGrid[grid]
    }
}

/**
 * Painted glyph renderer: parses the variant's stroke paths through the
 * committed FsdsSvgPath runtime and strokes them scaled to the frame.
 * Stroke inherits the tint (the currentColor analog); unknown names
 * render a dashed placeholder so a typo surfaces instead of silently
 * disappearing. Decorative semantics belong to the composing surface.
 */
@Composable
fun FsdsGlyphIcon(
    named: String,
    size: Dp,
    tint: Color,
    modifier: Modifier = Modifier,
) {
    val variant = FsdsGlyphCatalog.variant(named, size)
    val strokes: List<Pair<Path, Float>> = remember(named, variant) {
        variant?.paths?.map { stroke ->
            FsdsSvgPath.parse(stroke.d) to stroke.width
        } ?: emptyList()
    }
    Box(
        modifier.size(size).drawBehind {
            if (variant == null) {
                drawRoundRect(
                    color = tint,
                    topLeft = Offset.Zero,
                    size = this.size,
                    style = Stroke(
                        width = 1f,
                        pathEffect = PathEffect.dashPathEffect(floatArrayOf(2f, 2f)),
                    ),
                )
                return@drawBehind
            }
            val glyphScale = this.size.minDimension / variant.viewBox
            scale(glyphScale, pivot = Offset.Zero) {
                for ((p, w) in strokes) {
                    drawPath(
                        path = p,
                        color = tint,
                        style = Stroke(
                            width = w,
                            cap = StrokeCap.Round,
                            join = StrokeJoin.Round,
                        ),
                    )
                }
            }
        },
    )
}
